using System;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Media;
namespace Awl {partial class Shell {
 Brush GlassBrush(Color color,double opacity){return SurfaceBrush(color,opacity,cfg.GlassEffect);}
 Brush SurfaceBrush(Color color,double opacity,bool glass){byte alpha=(byte)(Math.Max(0,Math.Min(1,opacity))*255);if(!glass)return new SolidColorBrush(Color.FromArgb(alpha,color.R,color.G,color.B));Func<Color,Color> translucent=c=>Color.FromArgb(alpha,c.R,c.G,c.B);return new LinearGradientBrush(new GradientStopCollection{new GradientStop(translucent(Mix(color,Colors.White,.20)),0),new GradientStop(translucent(Mix(color,Colors.White,.075)),.15),new GradientStop(translucent(color),.48),new GradientStop(translucent(Mix(color,Colors.Black,.08)),1)},new Point(0,0),new Point(.15,1));}
 void ChooseWallpaperColor(string hex){var color=Parse(hex,baseColor);cfg.SelectedWallpaperColor=hex;cfg.Automatic=false;cfg.PaletteMode="Custom";cfg.DockColor=hex;double luminance=.2126*color.R+.7152*color.G+.0722*color.B;cfg.IconColor=luminance>155?"#142820":"#EDF8F0";Changed();}
 void WallpaperPresets(){page.Children.Add(Card("Wallpaper colors",()=>{var row=new UniformGrid{Columns=5};foreach(var sample in palette.Take(10)){var swatch=sample;var color=Parse(swatch.Hex,baseColor);var button=Action("",()=>ChooseWallpaperColor(swatch.Hex));button.Height=45;button.Padding=new Thickness(6);button.Background=GlassBrush(color,.95);button.ToolTip=swatch.Hex+" · "+swatch.Coverage.ToString("0.0")+"%";System.Windows.Automation.AutomationProperties.SetName(button,"Wallpaper color "+swatch.Hex);var mini=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};var contrast=new SolidColorBrush((color.R*.2126+color.G*.7152+color.B*.0722)>155?Color.FromRgb(20,40,32):Color.FromRgb(237,248,240));for(int i=0;i<4;i++){if(i==1)mini.Children.Add(new Border{Width=1,Height=16,Background=contrast,Opacity=.5,Margin=new Thickness(4,0,4,0)});mini.Children.Add(new Border{Width=12,Height=12,CornerRadius=new CornerRadius(3),Background=contrast,Opacity=.85,Margin=new Thickness(3)});}if(cfg.SelectedWallpaperColor==swatch.Hex&&!cfg.Automatic)mini.Children.Add(Text("✓",14,contrast));button.Content=mini;row.Children.Add(button);}page.Children.Add(row);if(palette.Count==0)page.Children.Add(Text("Choose a wallpaper to sample its colors",12,mutedBrush));var oldPage=page;var glassPanel=new StackPanel();page=glassPanel;GlassControls();page=oldPage;page.Children.Add(new Expander{Header="Glass effects",Foreground=ink,IsExpanded=false,Content=glassPanel});}));}
} }
